fn solve(n: i8) -> Vec<char> {
    // Compute the ones digit in 0..=9
    let digit = n.rem_euclid(10) as u8;

    // Pick the appropriate suffix
    let suffix = match digit {
        2 | 4 | 5 | 7 | 9 => "hon\n",
        3               => "bon\n",
        0 | 1 | 6 | 8   => "pon\n",
        _               => unreachable!(), // all 0..=9 are covered
    };

    // Convert the &str into Vec<char> and return
    suffix.chars().collect()
}

