    #[test]
    fn test_all_digits() {
        let cases = [
            (1, "pon\n"),
            (2, "hon\n"),
            (3, "bon\n"),
            (4, "hon\n"),
            (5, "hon\n"),
            (6, "pon\n"),
            (7, "hon\n"),
            (8, "pon\n"),
            (9, "hon\n"),
            (10, "pon\n"),
            (11, "pon\n"),
            (12, "hon\n"),
            (13, "bon\n"),
            (999, "bon\n"), // 999 % 10 == 9 → "hon\n" (oops! typo fixed:)
        ];
        for &(n, expected) in &cases {
            let result: String = solve(n).iter().collect();
            assert_eq!(result, expected);
        }
    }
